const SHOTS = RAW.map(([id, file, route, role, state, data, scrollTops, expect, note, fixtureTarget, blocked]) => ({
  id, file, route, role, state, data, scrollTops, expect, note, fixtureTarget, blocked: blocked || '',
}));

module.exports = SHOTS;

if (require.main === module) {
  const assert = require('assert');
  const fs = require('fs');
  const path = require('path');
  const xcxRoot = path.resolve(__dirname, '..');
  // 路由体检:矩阵引用了不存在的页面 → 拍出来是编译错误图,而脚本本身不会报错
  const dead = SHOTS
    .map((s) => ({ id: s.id, route: s.route.replace(/^\//, '').split('?')[0] }))
    .filter((s) => !fs.existsSync(path.join(xcxRoot, `${s.route}.wxml`)));
  assert.deepStrictEqual(dead, [], '引用了不存在的页面:' + dead.map((d) => `${d.id}→${d.route}`).join(', '));
  const ids = SHOTS.map((s) => s.id);
  const files = SHOTS.map((s) => s.file);
  assert.strictEqual(new Set(ids).size, ids.length, 'id 重复');
  assert.strictEqual(new Set(files).size, files.length, '文件名重复');
  for (const s of SHOTS) {
    assert.ok(s.expect && s.expect.selector && s.expect.min >= 1, `${s.id} 缺非恒真断言`);
    assert.ok(['player', 'merchant', 'club', 'guest'].includes(s.role), `${s.id} role 非法`);
    assert.ok(Array.isArray(s.scrollTops) && s.scrollTops.length, `${s.id} scrollTops 必须非空数组`);
  }
  const frames = SHOTS.reduce((a, s) => a + s.scrollTops.length, 0);
  console.log(`shot-extra-0808 selftest OK — ${SHOTS.length} 条 / ${frames} 张`);
}
